Lemma exec_fcmp_d : forall sz op rd rs1 rs2 c,
  exec sz (Fcmp op FMT_D rd rs1 rs2) c =
  EDone (rset rd (bword (fcmp_d op (fget c rs1) (fget c rs2)))
